import { chromium } from 'playwright';

const browser = await chromium.launch();
const base = 'http://localhost:6006/iframe.html?id=';

async function load(id, viewport = { width: 1440, height: 800 }, waitMs = 1500) {
  const page = await browser.newPage({ viewport });
  await page.goto(`${base}${id}&viewMode=story`, { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(waitMs);
  return page;
}

async function bodyText(page) {
  return page.evaluate(() => document.body.innerText.replace(/\s+/g, ' ').trim());
}

console.log('=== Commerce/ProductItem ===');
for (const id of [
  'commerce-productitem--default',
  'commerce-productitem--multiple-items',
  'commerce-productitem--gift-card',
  'commerce-productitem--with-error-message',
  'commerce-productitem--with-warning-message',
  'commerce-productitem--with-discount-label',
  'commerce-productitem--with-higher-max-order-quantity',
]) {
  const page = await load(id);
  const text = await bodyText(page);
  const info = await page.evaluate(() => {
    const stepperButtons = Array.from(document.querySelectorAll('button')).filter((b) =>
      /increase|decrease/i.test(b.getAttribute('aria-label') || ''),
    );
    const incrementDisabled = stepperButtons.find((b) => /increase/i.test(b.getAttribute('aria-label')))?.getAttribute('aria-disabled');
    const decrementDisabled = stepperButtons.find((b) => /decrease/i.test(b.getAttribute('aria-label')))?.getAttribute('aria-disabled');
    const value = document.querySelector('[aria-live="polite"]')?.textContent;
    return { hasStepperButtons: stepperButtons.length, incrementDisabled, decrementDisabled, value };
  });
  console.log(`\n--- ${id} ---`);
  console.log('text:', text.slice(0, 300));
  console.log('stepper info:', JSON.stringify(info));
  await page.close();
}

console.log('\n=== Elements/ZimmInlineMessage ===');
for (const id of [
  'elements-zimminlinemessage--default',
  'elements-zimminlinemessage--error-variant',
  'elements-zimminlinemessage--warning',
  'elements-zimminlinemessage--partially-out-of-stock',
  'elements-zimminlinemessage--max-quantity-reached',
  'elements-zimminlinemessage--success',
]) {
  const page = await load(id, { width: 800, height: 400 });
  const info = await page.evaluate(() => {
    const el = document.querySelector('[data-testid="zimm-inline-message"], [data-testid="zimm-discount-label"], p');
    const svg = document.querySelector('svg');
    return { text: el?.textContent, color: el ? getComputedStyle(el).color : null, hasIcon: !!svg };
  });
  console.log(`${id}:`, JSON.stringify(info));
  await page.close();
}

console.log('\n=== Commerce/ZimmQuantityStepper — Default only ===');
{
  const page = await load('commerce-zimmquantitystepper--default', { width: 400, height: 300 });
  const value = await page.evaluate(() => document.querySelector('[aria-live="polite"]')?.textContent);
  console.log('Default final value (after play, should be 3 mid-range no-op-net):', value);
  await page.close();
}

console.log('\n=== Commerce/ZimmCartDrawer ===');
for (const id of ['commerce-zimmcartdrawer--default', 'commerce-zimmcartdrawer--empty']) {
  const page = await load(id, { width: 1440, height: 900 });
  const info = await page.evaluate(() => ({
    title: document.querySelector('[id*="title"], h1, h2, span')?.closest('[role="dialog"]')?.getAttribute('aria-label') || document.body.innerText.split('\n')[0],
    bodyText: document.body.innerText.replace(/\s+/g, ' ').trim().slice(0, 200),
  }));
  console.log(`${id}:`, JSON.stringify(info));
  await page.close();
}

console.log('\n=== Elements/ZimmDrawer — X Large at tablet width (verify commit f80cc703 fix) ===');
{
  const page = await load('elements-zimmdrawer--x-large', { width: 834, height: 900 });
  const panelWidth = await page.evaluate(() => {
    const panel = document.querySelector('[role="dialog"], .chakra-modal__content, [class*="chakra-drawer"]');
    return panel ? panel.getBoundingClientRect().width : null;
  });
  console.log('X Large story at 834px viewport, panel width:', panelWidth, '(expect ~684px / 82%, NOT 834 full-bleed)');
  await page.close();
}

await browser.close();

