import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 800, height: 400 } });
const failed = [];
page.on('requestfailed', (req) => failed.push(`FAILED: ${req.url()} - ${req.failure()?.errorText}`));
page.on('response', (res) => {
  if (res.status() >= 400) failed.push(`HTTP ${res.status()}: ${res.url()}`);
});
page.on('console', (msg) => {
  if (msg.type() === 'error') console.log('CONSOLE ERROR:', msg.text());
});
page.on('pageerror', (err) => console.log('PAGE ERROR:', err.message, err.stack));

await page.goto('http://localhost:6006/iframe.html?id=elements-zimminlinemessage--default&viewMode=story', { waitUntil: 'networkidle', timeout: 30000 }).catch(e => console.log('goto error (expected if networkidle never settles):', e.message));
await page.waitForTimeout(3000);

console.log('Failed/error requests:', failed.length ? failed.join('\n') : 'none');

