import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 800, height: 400 } });

for (const id of [
  'elements-zimminlinemessage--default',
  'elements-zimminlinemessage--error-variant',
  'elements-zimminlinemessage--warning',
  'elements-zimminlinemessage--partially-out-of-stock',
  'elements-zimminlinemessage--max-quantity-reached',
  'elements-zimminlinemessage--success',
]) {
  await page.goto(`http://localhost:6006/?path=/story/${id}`, { waitUntil: 'load', timeout: 30000 });
  await page.waitForTimeout(1500);
  const frame = page.frames().find((f) => f.url().includes('iframe.html'));
  const info = frame
    ? await frame.evaluate(() => {
        const el = document.querySelector('p, [data-testid]');
        const svg = document.querySelector('svg');
        return { text: el?.textContent, color: el ? getComputedStyle(el).color : null, hasIcon: !!svg };
      })
    : { error: 'no iframe' };
  console.log(id, JSON.stringify(info));
}
await browser.close();

